RO_OFF, RO_VA, RO_SZ = 0x3000, 0x3000, 0x20cb
DA_OFF, DA_VA, DA_SZ = 0x6040, 0x7040, 0x818
GEAR_VA, GEAR_N = 0x7060, 255

def va2off(va):
    if RO_VA <= va < RO_VA + RO_SZ:
        return RO_OFF + (va - RO_VA)
    if DA_VA <= va < DA_VA + DA_SZ:
        return DA_OFF + (va - DA_VA)
    return None

def cstr(va, maxlen=200):
    off = va2off(va)
    if off is None: return None
    end = b.find(b'\0', off, off+maxlen)
    if end < 0: return None
    try:
        return b[off:end].decode('latin-1')
    except Exception:
        return None

print("== gear table ==")
ptrs = list(struct.unpack_from('<%dQ' % GEAR_N, b, DA_OFF + (GEAR_VA - DA_VA)))
print("count", len(ptrs), "min", hex(min(ptrs)), "max", hex(max(ptrs)))
print("first 5", [hex(x) for x in ptrs[:5]])
print("last 5", [hex(x) for x in ptrs[-5:]])

# Determine set of string starts in .rodata: positions where prev byte is 0 or start
ro = b[RO_OFF:RO_OFF+RO_SZ]
starts = set()
for i, ch in enumerate(ro):
    if ch != 0 and (i == 0 or ro[i-1] == 0):
        starts.add(RO_VA + i)

print("\n== pointer classification ==")
bad = []
for i, va in enumerate(ptrs):
    s = cstr(va)
    is_start = va in starts
    if s is None or not is_start:
        bad.append((i, va, is_start, s))
# report anomalies (not at string start, or no string)
for i, va, is_start, s in bad:
    print("idx %3d ptr %#x start=%s str=%r" % (i, va, is_start, (s[:60] if s else s)))
print("anomaly count:", len(bad))

print("\n== duplicates ==")
from collections import Counter
c = Counter(ptrs)
dups = {k: v for k, v in c.items() if v > 1}
print("dup ptrs:", {hex(k): v for k, v in dups.items()})

print("\n== monotonic/range check ==")
print("all within rodata:", all(RO_VA <= v < RO_VA+RO_SZ for v in ptrs))
print("sorted:", ptrs == sorted(ptrs))

print("\n== vaddr 0x4C50 ==")
print("0x4C50 in rodata:", RO_VA <= 0x4C50 < RO_VA+RO_SZ)
print("string at 0x4C50:", repr(cstr(0x4C50)))
print("is 0x4C50 a string start:", 0x4C50 in starts)
print("0x4C50 in gear pointers:", 0x4C50 in ptrs)
# print rodata around 0x4C00..0x4D00
o = va2off(0x4C00)
print("rodata 0x4C00..0x4D00 bytes:", b[o:o+0x100])
print("strings in 0x4B00..0x4E00:")
for s in sorted(x for x in starts if 0x4A00 <= x < 0x4E00):
