print("\n== HTB{ occurrences in whole file ==")
for m in re.finditer(rb'HTB\{', b):
    va = None
    o = m.start()
    if RO_OFF <= o < RO_OFF+RO_SZ: va = RO_VA + (o-RO_OFF)
    if DA_OFF <= o < DA_OFF+DA_SZ: va = DA_VA + (o-DA_OFF)
    end = b.find(b'\0', o)
    print(" off %#x vaddr %s : %r" % (o, hex(va) if va else '?', b[o:end][:80]))

print("\n== strings >= 6 chars that are not item-like (contain { or } or HTB) ==")
for i, ch in enumerate(ro):
    if ch != 0 and (i == 0 or ro[i-1] == 0):
