#include <string.h>
#include <stdint.h>

static int asm_index(int r) {
    /* exact emulation of main() sequence */
    uint64_t rcx = (uint64_t)(int64_t)r;
    uint64_t M = 0x8080808080808081ULL;
    __uint128_t prod = (__uint128_t)rcx * M;
    uint64_t rdx = (uint64_t)(prod >> 64);
    rdx >>= 10;
    uint64_t rax = rdx << 8;
    rax = rax - rdx;
    rax <<= 3;
    rcx = rcx - rax;
    int64_t rem = (int64_t)rcx;
    return (int)(rem >> 3);
}

int main(int argc, char **argv) {
    if (argc >= 2 && strcmp(argv[1], "verify") == 0) {
        /* compare asm emulation with rand()%2040/8 across many seeds/values */
        long bad = 0;
        for (unsigned seed = 0; seed < 20000; seed++) {
            srand(seed);
            for (int i = 0; i < 50; i++) {
                int r = rand();
                int a = asm_index(r);
                int c = (r % 2040) / 8;
                if (a != c) { if (bad < 10) printf("MISMATCH seed=%u r=%d asm=%d c=%d\n", seed, r, a, c); bad++; }
            }
        }
        /* also edge random values */
        int edges[] = {0, 1, 7, 8, 2039, 2040, 2041, 2147483647, 2147483646, 123456789, 1073741824};
        for (int i = 0; i < (int)(sizeof(edges)/sizeof(edges[0])); i++) {
            int a = asm_index(edges[i]);
            int c = (edges[i] % 2040) / 8;
            if (a != c) { printf("EDGE MISMATCH r=%d asm=%d c=%d\n", edges[i], a, c); bad++; }
        }
        printf("verify done, mismatches=%ld\n", bad);
        return 0;
    }
    if (argc >= 4 && strcmp(argv[1], "search") == 0) {
        long long lo = atoll(argv[2]), hi = atoll(argv[3]);
        int target = (argc >= 5) ? atoi(argv[4]) : -1;
        long long n = 0;
        for (long long t = lo; t < hi; t++) {
            srand((unsigned)t);
            int r = rand();
            int idx = (r % 2040) / 8;
            if (idx == target) {
                if (n < 40) printf("seed=%lld rand=%d idx=%d\n", t, r, idx);
                n++;
            }
        }
        printf("matches=%lld in [%lld,%lld) target=%d\n", n, lo, hi, target);
        return 0;
    }
    if (argc >= 3 && strcmp(argv[1], "seed") == 0) {
        long long t = atoll(argv[2]);
        srand((unsigned)t);
        int r = rand();
        int r2 = rand();
        printf("seed=%lld first rand=%d idx=%d asm=%d second_rand=%d idx2=%d\n",
               t, r, (r % 2040) / 8, asm_index(r), r2, (r2 % 2040) / 8);
        return 0;
    }
    fprintf(stderr, "usage: %s verify | seed <t> | search <lo> <hi> <target>\n", argv[0]);
    return 1;
}
